def cyclicShift(n, grid, rowShift, colShift):
    # Phase 1: shift every row to the left by rowShift[i]
    temp = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # Element at column j moves to column (j - shift + n) % n
            temp[i][(j - rowShift[i] + n) % n] = grid[i][j]

    # Phase 2: shift every column upward by colShift[j], using the row-shifted grid
    result = [[0] * n for _ in range(n)]
    for j in range(n):
        for i in range(n):
            # Element at row i moves to row (i - shift + n) % n
            result[(i - colShift[j] + n) % n][j] = temp[i][j]

    return result
